marker = 'export default function Home() {'
component = '''function EtaHistoryChart({ history, train, offsetMinutes, onSeek, playing, onToggle }: { history: Array<{ etaMinutes: number; scheduledMinutes: number; confidence: number }>; train: typeof fleet[number]; offsetMinutes: number; onSeek: (delta: number) => void; playing: boolean; onToggle: () => void }) {
  const fallback = [18, 14, 11, 8, 6, 4, 2, 1, 3, 2, 1, 0].map((variance, index) => ({ etaMinutes: 642 + index * 5 + variance, scheduledMinutes: 642 + index * 5, confidence: Math.max(72, train.confidence - Math.abs(variance)) }));
  const points = history.length ? history.slice().reverse() : fallback;
  const min = Math.min(...points.map((point) => point.etaMinutes - point.scheduledMinutes), -4);
  const max = Math.max(...points.map((point) => point.etaMinutes - point.scheduledMinutes), 6);
  const width = 460; const height = 116; const range = Math.max(1, max - min);
  const line = points.map((point, index) => `${(index / Math.max(1, points.length - 1)) * width},${height - (((point.etaMinutes - point.scheduledMinutes) - min) / range) * height}`).join(" ");
  const latest = points[points.length - 1];
  return <div className="history-panel panel"><div className="panel-head"><div><span className="panel-kicker">ETA HISTORY / LAST 24 READINGS</span><h3>Forecast drift, in motion</h3></div><span className="model-tag">{history.length ? "STORED" : "LIVE SAMPLE"}</span></div><div className="history-toolbar"><div><strong>{latest ? `${latest.etaMinutes - latest.scheduledMinutes >= 0 ? "+" : ""}${latest.etaMinutes - latest.scheduledMinutes} min` : "—"}</strong><small>latest variance · {latest?.confidence ?? train.confidence}% confidence</small></div><div className="playback-controls"><button onClick={() => onSeek(-15)} aria-label="Rewind 15 minutes"><ChevronLeft size={14} /></button><button className="play-button" onClick={onToggle} aria-label={playing ? "Pause playback" : "Play playback"}>{playing ? <Pause size={13} /> : <Play size={13} />}</button><button onClick={() => onSeek(15)} aria-label="Advance 15 minutes"><ChevronRight size={14} /></button></div></div><div className="history-chart"><svg viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none"><line x1="0" x2={width} y1={height - (((0 - min) / range) * height)} y2={height - (((0 - min) / range) * height)} className="history-zero" /><polyline points={line} className="history-line" fill="none" /><circle cx={points.length ? ((points.length - 1) / Math.max(1, points.length - 1)) * width : 0} cy={latest ? height - (((latest.etaMinutes - latest.scheduledMinutes - min) / range) * height) : height / 2} r="4" className="history-point" /></svg><div className="history-axis"><span>−60m</span><span>−30m</span><span>now</span></div></div><div className="history-footer"><span><i className="legend-dot aqua" /> ETA variance</span><span><i className="legend-dot gold" /> playback offset {offsetMinutes >= 0 ? "+" : ""}{offsetMinutes}m</span><span className="mono">{history.length ? "persisted telemetry" : "awaiting stored readings"}</span></div></div>;
}

'''
