s = s.replace('onClick={() => { setSelectedTrain(0); setActiveView("passenger"); }}', 'onClick={() => { setSelectedTrain(0); setActiveView("passenger"); sendAction("SELECT_TRAIN", { index: 0 }); sendAction("NAVIGATE_VIEW", { view: "passenger" }); }}')
