s = s.replace('</div></div></section>}\n\n        {activeView === "sandbox"', '<EtaHistoryChart history={etaHistoryQuery.data ?? []} train={selected} offsetMinutes={playbackOffsetMinutes} playing={playbackPlaying} onToggle={() => { const next = !playbackPlaying; setPlaybackPlaying(next); sendAction("TOGGLE_PLAYBACK", { playing: next }); }} onSeek={(delta) => { const next = Math.max(-120, Math.min(120, playbackOffsetMinutes + delta)); setPlaybackOffsetMinutes(next); sendAction("PLAYBACK_SEEK", { offsetMinutes: next }); }} /></div></section>}\n\n        {activeView === "sandbox"')
